cypress_script:
describe('File Upload and Download', () => {
  it('should successfully upload a file', () => {
    cy.visit('https://demoqa.com/upload-download');
    const filePath = 'path/to/your/test/file.txt';
    cy.get('#uploadFile').attachFile(filePath);
    // Verify that the file is uploaded successfully (this will depend on the application behavior)
  });

  it('should not change the URL when no file is uploaded', () => {
    cy.visit('https://demoqa.com/upload-download');
    cy.get('#uploadFile').clear();
    cy.url().should('eq', 'https://demoqa.com/upload-download');
    cy.get('#downloadButton').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('File Upload and Download', () => {
  test('should successfully upload a file', async ({ page }) => {
    await page.goto('https://demoqa.com/upload-download');
    const filePath = 'path/to/your/test/file.txt';
    await page.setInputFiles('#uploadFile', filePath);
    // Verify that the file is uploaded successfully (this will depend on the application behavior)
  });

  test('should not change the URL when no file is uploaded', async ({ page }) => {
    await page.goto('https://demoqa.com/upload-download');
    await page.fill('#uploadFile', '');
    await expect(page).toHaveURL('https://demoqa.com/upload-download');
    await expect(page.locator('#downloadButton')).toBeVisible();
  });
});
